/**
 * LearnHouse V2 design tokens: the single source for the look shared by the
 * dashboard and the learner side.
 *
 * These values were read off the redesigned pages (DashKit, AIBrand, the
 * analytics kit, focus mode); they describe what is already on screen, not a
 * new look. Every token that has a `cssVar` is mirrored in styles/globals.css
 * between the `@design-tokens` markers (generated by design/tokensCss.ts,
 * checked by tests/design-tokens.test.mjs), which makes Tailwind utilities:
 *
 *   --color-lh-*    bg-lh-surface, text-lh-fg-muted, ring-lh-border-strong
 *   --radius-lh-*   rounded-lh-card
 *   --shadow-lh-*   shadow-lh-floating
 *   --spacing-lh-*  px-lh-gutter, gap-lh-section
 *   --text-lh-*     text-lh-meta
 *   --ease-lh-*     ease-lh-out
 *   --lh-duration-* plain variables, for style props and CSS files
 *
 * Pure module: no React, no path aliases, so server code, scripts and the
 * unit tests can import it as is.
 *
 * To change a token: edit it here, run `bun scripts/design-tokens.mjs` from
 * apps/web to rewrite the CSS block, then check /design-system in dev.
 */

export type Token = {
  /** CSS custom property, when the token is mirrored in globals.css. */
  cssVar?: string
  /** The CSS value (may reference Tailwind palette variables or the org theme). */
  value: string
  /** Approximate sRGB hex, for JS consumers that cannot read CSS (charts, canvas, emails). */
  hex?: string
  /** The Tailwind classes existing pages use for this token. */
  tailwind?: string
  /** Where it is used. */
  use: string
}

const c = (name: string, value: string, hex: string, tailwind: string, use: string): Token => ({
  cssVar: `--color-lh-${name}`,
  value,
  hex,
  tailwind,
  use,
})

