/** Everything, for the style guide and the sync test. */
export const tokens = { color, radius, shadow, spacing, text, font, motion, zIndex, icon, layout, chartSeries } as const

/** Every token mirrored in CSS, in emit order. */
export function cssTokenList(): { group: string; cssVar: string; value: string }[] {
  const groups: [string, Record<string, Token>][] = [
    ['color', color],
    ['radius', radius],
    ['shadow', shadow],
    ['spacing', spacing],
    ['text', text],
    ['motion', motion],
  ]
  const out: { group: string; cssVar: string; value: string }[] = []
  for (const [group, entries] of groups) {
    for (const token of Object.values(entries)) {
      if (token.cssVar) out.push({ group, cssVar: token.cssVar, value: token.value })
    }
  }
  return out
}
